<script setup lang="ts">
const selection=useSelection();
const groups=computed(()=>{const values=new Map<string,{key:string;reference:string;name:string;image:string;colorName:string;indexes:number[]}>();selection.lines.forEach((line,index)=>{const key=line.reference+':'+line.color;const group=values.get(key)||{key,reference:line.reference,name:line.name,image:line.image,colorName:line.colorName,indexes:[]};group.indexes.push(index);values.set(key,group);});return [...values.values()];});
function remove(indexes:number[]){selection.lines=selection.lines.filter((_,i)=>!indexes.includes(i));}
</script>
<template><div class="order-groups"><article v-for="group in groups" :key="group.key" class="order-group"><div class="order-group-title"><img :src="group.image" :alt="group.name" width="50" height="62"/><div><small>{{group.reference}}</small><h3>{{group.name}}</h3><span>{{group.colorName}} · {{group.indexes.reduce((sum,i)=>sum+(Number(selection.lines[i]?.quantity)||0),0)}} prendas</span></div><button type="button" class="icon-button" :aria-label="`Quitar ${group.reference}, ${group.colorName}`" @click="remove(group.indexes)"><AppIcon name="X" :size="18"/></button></div><div class="order-group-sizes"><label v-for="i in group.indexes" :key="i"><span>{{selection.lines[i]?.size}}</span><input v-if="selection.lines[i]" v-model.number="selection.lines[i]!.quantity" type="number" min="1" max="10000" step="1" inputmode="numeric" :aria-label="`Editar cantidad ${group.reference}, ${group.colorName}, talla ${selection.lines[i]?.size}`" :aria-invalid="!Number.isInteger(selection.lines[i]?.quantity)||(selection.lines[i]?.quantity||0)<1||(selection.lines[i]?.quantity||0)>10000"/></label></div><p v-if="group.indexes.some(i=>!Number.isInteger(selection.lines[i]?.quantity)||(selection.lines[i]?.quantity||0)<1||(selection.lines[i]?.quantity||0)>10000)" class="field-error">Usa cantidades enteras entre 1 y 10.000.</p></article></div></template>
